begin;

create temporary table coding_question_seed (collection_slug text not null, slug text not null, title text not null, problem_statement text not null, difficulty text not null, topic_tags text[] not null, constraints jsonb not null, examples jsonb not null, starter_code_by_language jsonb not null, points integer not null) on commit drop;

insert into coding_question_seed select collection_slug,slug,title,problem_statement,difficulty,topic_tags,constraints,examples,starter_code_by_language,points from jsonb_to_recordset($seed$[{"collection_slug":"backend-api-problem-solving","slug":"parse-retry-after-seconds","title":"Parse Retry-After Seconds","problem_statement":"Parse Retry-After integer seconds into milliseconds; accept non-negative digits only. For example, the numeric header 120 represents a two-minute delay; do not parse an HTTP-date form.","difficulty":"Easy","topic_tags":["Backend API","Reliability"],"constraints":["Inputs use the types and shapes shown in the examples.","Do not mutate caller-owned inputs.","Follow the stated behavior for malformed values."],"examples":[{"input":"\"120\"","output":"120000"},{"input":"\"7\"","output":"7000"}],"starter_code_by_language":{"JavaScript":"function parseRetryAfterSeconds(value) {\n  throw new Error(\"Not implemented\");\n}","Python":"def parse_retry_after_seconds(value):\n    raise NotImplementedError"},"points":100},{"collection_slug":"backend-api-problem-solving","slug":"classify-retryable-status","title":"Classify Retryable HTTP Status","problem_statement":"Return true for 408, 425, 429, and status codes 500-599; otherwise false. Treat each supported code as retryable independent of method or response body; do not classify redirects or ordinary client errors as retryable.","difficulty":"Medium","topic_tags":["Backend API","Reliability"],"constraints":["Inputs use the types and shapes shown in the examples.","Do not mutate caller-owned inputs.","Follow the stated behavior for malformed values."],"examples":[{"input":"503","output":"true"},{"input":"429","output":"true"}],"starter_code_by_language":{"JavaScript":"function classifyRetryableStatus(status) {\n  throw new Error(\"Not implemented\");\n}","Python":"def classify_retryable_status(status):\n    raise NotImplementedError"},"points":150},{"collection_slug":"backend-api-problem-solving","slug":"normalize-http-method","title":"Normalize HTTP Method","problem_statement":"Trim and uppercase a method, accepting only GET, HEAD, POST, PUT, PATCH, DELETE, OPTIONS, and TRACE; unsupported tokens return null.","difficulty":"Hard","topic_tags":["Backend API","Reliability"],"constraints":["Inputs use the types and shapes shown in the examples.","Do not mutate caller-owned inputs.","Follow the stated behavior for malformed values."],"examples":[{"input":"\" post \"","output":"POST"},{"input":"\"TRACE\"","output":"TRACE"}],"starter_code_by_language":{"JavaScript":"function normalizeHttpMethod(method) {\n  throw new Error(\"Not implemented\");\n}","Python":"def normalize_http_method(method):\n    raise NotImplementedError"},"points":200},{"collection_slug":"backend-api-problem-solving","slug":"parse-content-length","title":"Parse Content-Length","problem_statement":"Parse a digit-only string as a safe non-negative integer. Reject signs, decimals, whitespace, and unsafe integers.","difficulty":"Easy","topic_tags":["Backend API","Reliability"],"constraints":["Inputs use the types and shapes shown in the examples.","Do not mutate caller-owned inputs.","Follow the stated behavior for malformed values."],"examples":[{"input":"\"0042\"","output":"42"},{"input":"\"900\"","output":"900"}],"starter_code_by_language":{"JavaScript":"function parseContentLength(value) {\n  throw new Error(\"Not implemented\");\n}","Python":"def parse_content_length(value):\n    raise NotImplementedError"},"points":100},{"collection_slug":"backend-api-problem-solving","slug":"parse-page-window","title":"Build a Bounded Page Window","problem_statement":"Given zero-based page, requested limit, and total row count, clamp limit to 1..100 and page to the last available page. Return offset, limit, and totalPages; an empty collection has offset 0 and zero totalPages.","difficulty":"Medium","topic_tags":["Backend API","Reliability"],"constraints":["Inputs use the types and shapes shown in the examples.","Do not mutate caller-owned inputs.","Follow the stated behavior for malformed values."],"examples":[{"input":"{\"page\":2,\"requestedLimit\":10,\"total\":23}","output":"{\"offset\":20,\"limit\":10,\"totalPages\":3}"},{"input":"{\"page\":99,\"requestedLimit\":0,\"total\":6}","output":"{\"offset\":5,\"limit\":1,\"totalPages\":6"}],"starter_code_by_language":{"JavaScript":"function pageWindow(page, requestedLimit, total) {\n  throw new Error(\"Not implemented\");\n}","Python":"def page_window(page, requested_limit, total):\n    raise NotImplementedError"},"points":150},{"collection_slug":"backend-api-problem-solving","slug":"merge-overlapping-pages","title":"Merge Overlapping Page Results","problem_statement":"Concatenate two page arrays and keep the first record for each non-null id. Preserve first-occurrence order; discard records without ids.","difficulty":"Hard","topic_tags":["Backend API","Reliability"],"constraints":["Inputs use the types and shapes shown in the examples.","Do not mutate caller-owned inputs.","Follow the stated behavior for malformed values."],"examples":[{"input":"{\"first\":[{\"id\":\"a\",\"v\":1},{\"id\":\"b\"}],\"second\":[{\"id\":\"b\",\"v\":9},{\"id\":\"c\"}]}","output":"[{\"id\":\"a\",\"v\":1},{\"id\":\"b\"},{\"id\":\"c\"}]"},{"input":"{\"first\":[{\"id\":2}],\"second\":[{\"id\":3}]}","output":"[{\"id\":2},{\"id\":3}]"}],"starter_code_by_language":{"JavaScript":"function mergeOverlappingPages(first, second) {\n  throw new Error(\"Not implemented\");\n}","Python":"def merge_overlapping_pages(first, second):\n    raise NotImplementedError"},"points":200},{"collection_slug":"backend-api-problem-solving","slug":"detect-repeated-cursor","title":"Detect a Pagination Loop","problem_statement":"Return true only when the proposed non-empty cursor already appears in the list of previously used cursors.","difficulty":"Easy","topic_tags":["Backend API","Reliability"],"constraints":["Inputs use the types and shapes shown in the examples.","Do not mutate caller-owned inputs.","Follow the stated behavior for malformed values."],"examples":[{"input":"{\"seen\":[\"c1\",\"c2\",\"c3\"],\"nextCursor\":\"c2\"}","output":"true"},{"input":"{\"seen\":[\"c1\",\"c2\"],\"nextCursor\":\"c4\"}","output":"false"}],"starter_code_by_language":{"JavaScript":"function hasRepeatedCursor(seen, nextCursor) {\n  throw new Error(\"Not implemented\");\n}","Python":"def has_repeated_cursor(seen, next_cursor):\n    raise NotImplementedError"},"points":100},{"collection_slug":"backend-api-problem-solving","slug":"filter-rows-after-cursor","title":"Filter Rows After a Composite Cursor","problem_statement":"Rows are ordered by numeric createdAt and then string id. Return rows strictly after the [createdAt,id] cursor, preserving their input order.","difficulty":"Medium","topic_tags":["Backend API","Reliability"],"constraints":["Inputs use the types and shapes shown in the examples.","Do not mutate caller-owned inputs.","Follow the stated behavior for malformed values."],"examples":[{"input":"{\"rows\":[{\"createdAt\":10,\"id\":\"a\"},{\"createdAt\":10,\"id\":\"c\"},{\"createdAt\":11,\"id\":\"a\"}],\"cursor\":[10,\"b\"]}","output":"[{\"createdAt\":10,\"id\":\"c\"},{\"createdAt\":11,\"id\":\"a\"}]"},{"input":"{\"rows\":[{\"createdAt\":7,\"id\":\"z\"},{\"createdAt\":9,\"id\":\"a\"}],\"cursor\":[8,\"a\"]}","output":"[{\"createdAt\":9,\"id\":\"a\"}]"}],"starter_code_by_language":{"JavaScript":"function rowsAfterCursor(rows, cursor) {\n  throw new Error(\"Not implemented\");\n}","Python":"def rows_after_cursor(rows, cursor):\n    raise NotImplementedError"},"points":150},{"collection_slug":"backend-api-problem-solving","slug":"remove-sensitive-query-keys","title":"Remove Sensitive Query Parameters","problem_statement":"Remove query pairs whose key is token, key, password, or signature, ignoring case. Preserve the order and values of other pairs.","difficulty":"Hard","topic_tags":["Backend API","Reliability"],"constraints":["Inputs use the types and shapes shown in the examples.","Do not mutate caller-owned inputs.","Follow the stated behavior for malformed values."],"examples":[{"input":"[[\"page\",\"2\"],[\"Token\",\"abc\"],[\"q\",\"retry\"],[\"signature\",\"xyz\"]]","output":"[[\"page\",\"2\"],[\"q\",\"retry\"]]"},{"input":"[[\"api_key\",\"public\"],[\"PASSWORD\",\"x\"],[\"lang\",\"en\"]]","output":"[[\"api_key\",\"public\"],[\"lang\",\"en\"]]"}],"starter_code_by_language":{"JavaScript":"function removeSensitiveQueryKeys(pairs) {\n  throw new Error(\"Not implemented\");\n}","Python":"def remove_sensitive_query_keys(pairs):\n    raise NotImplementedError"},"points":200},{"collection_slug":"backend-api-problem-solving","slug":"validate-sort-specification","title":"Validate Sort Specification","problem_statement":"Accept at most three sort descriptors. Each must name an allowlisted field and use direction asc or desc; reject malformed descriptors and duplicate fields.","difficulty":"Easy","topic_tags":["Backend API","Reliability"],"constraints":["Inputs use the types and shapes shown in the examples.","Do not mutate caller-owned inputs.","Follow the stated behavior for malformed values."],"examples":[{"input":"{\"sort\":[{\"field\":\"createdAt\",\"direction\":\"desc\"},{\"field\":\"id\",\"direction\":\"asc\"}],\"allowedFields\":[\"createdAt\",\"id\"]}","output":"true"},{"input":"{\"sort\":[{\"field\":\"email\",\"direction\":\"asc\"}],\"allowedFields\":[\"createdAt\",\"id\"]}","output":"false"}],"starter_code_by_language":{"JavaScript":"function isValidSort(sort, allowedFields) {\n  throw new Error(\"Not implemented\");\n}","Python":"def is_valid_sort(sort, allowed_fields):\n    raise NotImplementedError"},"points":100},{"collection_slug":"backend-api-problem-solving","slug":"find-missing-request-fields","title":"Find Missing Required Fields","problem_statement":"Return required names whose value is absent, null, or blank. Numeric zero and boolean false count as present; preserve required-list order.","difficulty":"Medium","topic_tags":["Backend API","Reliability"],"constraints":["Inputs use the types and shapes shown in the examples.","Do not mutate caller-owned inputs.","Follow the stated behavior for malformed values."],"examples":[{"input":"{\"required\":[\"name\",\"active\",\"quota\"],\"values\":{\"name\":\"Ada\",\"active\":false}}","output":"[\"quota\"]"},{"input":"{\"required\":[\"email\",\"region\"],\"values\":{\"email\":\" \"}}","output":"[\"email\",\"region\"]"}],"starter_code_by_language":{"JavaScript":"function missingFields(required, values) {\n  throw new Error(\"Not implemented\");\n}","Python":"def missing_fields(required, values):\n    raise NotImplementedError"},"points":150},{"collection_slug":"backend-api-problem-solving","slug":"redact-error-secrets","title":"Redact Secrets from Error Objects","problem_statement":"Recursively clone arrays and objects, replacing values of password, token, secret, or authorization keys (case-insensitive) with [REDACTED]. Preserve other values.","difficulty":"Hard","topic_tags":["Backend API","Reliability"],"constraints":["Inputs use the types and shapes shown in the examples.","Do not mutate caller-owned inputs.","Follow the stated behavior for malformed values."],"examples":[{"input":"{\"message\":\"denied\",\"token\":\"abc\",\"details\":{\"password\":\"pw\",\"field\":\"email\"}}","output":"{\"message\":\"denied\",\"token\":\"[REDACTED]\",\"details\":{\"password\":\"[REDACTED]\",\"field\":\"email\"}}"},{"input":"[{\"Authorization\":\"Bearer x\"},{\"code\":\"E1\"}]","output":"[{\"Authorization\":\"[REDACTED]\"},{\"code\":\"E1\"}]"}],"starter_code_by_language":{"JavaScript":"function redactErrorSecrets(value) {\n  throw new Error(\"Not implemented\");\n}","Python":"def redact_error_secrets(value):\n    raise NotImplementedError"},"points":200},{"collection_slug":"backend-api-problem-solving","slug":"chunk-bulk-request","title":"Chunk a Bulk Request","problem_statement":"Split an input array into consecutive chunks of a positive integer size without reordering or modifying elements.","difficulty":"Easy","topic_tags":["Backend API","Reliability"],"constraints":["Inputs use the types and shapes shown in the examples.","Do not mutate caller-owned inputs.","Follow the stated behavior for malformed values."],"examples":[{"input":"{\"items\":[{\"id\":1},{\"id\":2},{\"id\":3},{\"id\":4},{\"id\":5}],\"size\":2}","output":"[[{\"id\":1},{\"id\":2}],[{\"id\":3},{\"id\":4}],[{\"id\":5}]]"},{"input":"{\"items\":[\"a\",\"b\",\"c\"],\"size\":2}","output":"[[\"a\",\"b\"],[\"c\"]]"}],"starter_code_by_language":{"JavaScript":"function chunkBulkRequest(items, size) {\n  throw new Error(\"Not implemented\");\n}","Python":"def chunk_bulk_request(items, size):\n    raise NotImplementedError"},"points":100},{"collection_slug":"backend-api-problem-solving","slug":"partition-bulk-outcomes","title":"Partition Bulk Outcomes","problem_statement":"Partition result objects into succeeded and failed arrays according to boolean ok. Preserve order and ignore entries without a boolean ok.","difficulty":"Medium","topic_tags":["Backend API","Reliability"],"constraints":["Inputs use the types and shapes shown in the examples.","Do not mutate caller-owned inputs.","Follow the stated behavior for malformed values."],"examples":[{"input":"[{\"id\":\"a\",\"ok\":true},{\"id\":\"b\",\"ok\":false,\"error\":\"timeout\"},{\"id\":\"c\",\"ok\":true}]","output":"{\"succeeded\":[{\"id\":\"a\",\"ok\":true},{\"id\":\"c\",\"ok\":true}],\"failed\":[{\"id\":\"b\",\"ok\":false,\"error\":\"timeout\"}]}"},{"input":"[{\"id\":\"x\"},{\"id\":\"y\",\"ok\":false}]","output":"{\"succeeded\":[],\"failed\":[{\"id\":\"y\",\"ok\":false}]}"}],"starter_code_by_language":{"JavaScript":"function partitionBulkOutcomes(results) {\n  throw new Error(\"Not implemented\");\n}","Python":"def partition_bulk_outcomes(results):\n    raise NotImplementedError"},"points":150},{"collection_slug":"backend-api-problem-solving","slug":"compute-exponential-retry-delays","title":"Compute Capped Exponential Retry Delays","problem_statement":"Return retryCount delays beginning at baseMs and doubling each attempt, capped at maxMs. The first attempt uses the base delay, and every later value is the doubled predecessor unless the configured cap is lower.","difficulty":"Hard","topic_tags":["Backend API","Reliability"],"constraints":["Inputs use the types and shapes shown in the examples.","Do not mutate caller-owned inputs.","Follow the stated behavior for malformed values."],"examples":[{"input":"{\"baseMs\":100,\"retryCount\":5,\"maxMs\":500}","output":"[100,200,400,500,500]"},{"input":"{\"baseMs\":75,\"retryCount\":3,\"maxMs\":1000}","output":"[75,150,300]"}],"starter_code_by_language":{"JavaScript":"function retryDelays(baseMs, retryCount, maxMs) {\n  throw new Error(\"Not implemented\");\n}","Python":"def retry_delays(base_ms, retry_count, max_ms):\n    raise NotImplementedError"},"points":200},{"collection_slug":"backend-api-problem-solving","slug":"validate-idempotency-key","title":"Validate an Idempotency Key","problem_statement":"Accept strings 16 through 128 characters long containing only ASCII letters, digits, underscore, or hyphen.","difficulty":"Easy","topic_tags":["Backend API","Reliability"],"constraints":["Inputs use the types and shapes shown in the examples.","Do not mutate caller-owned inputs.","Follow the stated behavior for malformed values."],"examples":[{"input":"\"order_20261029_ab12\"","output":"true"},{"input":"\"order key 1\"","output":"false"}],"starter_code_by_language":{"JavaScript":"function isValidIdempotencyKey(key) {\n  throw new Error(\"Not implemented\");\n}","Python":"def is_valid_idempotency_key(key):\n    raise NotImplementedError"},"points":100},{"collection_slug":"backend-api-problem-solving","slug":"compare-json-payloads","title":"Compare JSON Payloads Structurally","problem_statement":"Return true for structurally equal JSON values regardless of object key order. Array order and primitive types remain significant.","difficulty":"Medium","topic_tags":["Backend API","Reliability"],"constraints":["Inputs use the types and shapes shown in the examples.","Do not mutate caller-owned inputs.","Follow the stated behavior for malformed values."],"examples":[{"input":"{\"first\":{\"a\":1,\"meta\":{\"x\":true}},\"second\":{\"meta\":{\"x\":true},\"a\":1}}","output":"true"},{"input":"{\"first\":[1,2],\"second\":[2,1]}","output":"false"}],"starter_code_by_language":{"JavaScript":"function structurallyEqualJson(first, second) {\n  throw new Error(\"Not implemented\");\n}","Python":"def structurally_equal_json(first, second):\n    raise NotImplementedError"},"points":150},{"collection_slug":"backend-api-problem-solving","slug":"resolve-idempotency-state","title":"Resolve Idempotency Record State","problem_statement":"Map pending to in-progress, completed to replay, and failed to retryable. Any unrecognized state maps to conflict.","difficulty":"Hard","topic_tags":["Backend API","Reliability"],"constraints":["Inputs use the types and shapes shown in the examples.","Do not mutate caller-owned inputs.","Follow the stated behavior for malformed values."],"examples":[{"input":"\"completed\"","output":"replay"},{"input":"\"failed\"","output":"retryable"}],"starter_code_by_language":{"JavaScript":"function resolveIdempotencyState(state) {\n  throw new Error(\"Not implemented\");\n}","Python":"def resolve_idempotency_state(state):\n    raise NotImplementedError"},"points":200},{"collection_slug":"backend-api-problem-solving","slug":"calculate-token-bucket-wait","title":"Calculate Token Bucket Wait","problem_statement":"Calculate ceiling milliseconds needed to refill a positive token deficit at a positive tokens-per-second rate. Return zero for no deficit and null for a non-positive rate.","difficulty":"Easy","topic_tags":["Backend API","Reliability"],"constraints":["Inputs use the types and shapes shown in the examples.","Do not mutate caller-owned inputs.","Follow the stated behavior for malformed values."],"examples":[{"input":"{\"deficit\":3,\"refillPerSecond\":4}","output":"750"},{"input":"{\"deficit\":2,\"refillPerSecond\":8}","output":"250"}],"starter_code_by_language":{"JavaScript":"function tokenBucketWaitMs(deficit, refillPerSecond) {\n  throw new Error(\"Not implemented\");\n}","Python":"def token_bucket_wait_ms(deficit, refill_per_second):\n    raise NotImplementedError"},"points":100},{"collection_slug":"backend-api-problem-solving","slug":"count-sliding-window-requests","title":"Count Sliding Window Requests","problem_statement":"Count timestamps in the inclusive interval from now-windowMs through now. Ignore older timestamps and future timestamps.","difficulty":"Medium","topic_tags":["Backend API","Reliability"],"constraints":["Inputs use the types and shapes shown in the examples.","Do not mutate caller-owned inputs.","Follow the stated behavior for malformed values."],"examples":[{"input":"{\"times\":[899,900,950,1000,1001],\"now\":1000,\"windowMs\":100}","output":"3"},{"input":"{\"times\":[10,20,30,40],\"now\":35,\"windowMs\":20}","output":"2"}],"starter_code_by_language":{"JavaScript":"function countWindowRequests(times, now, windowMs) {\n  throw new Error(\"Not implemented\");\n}","Python":"def count_window_requests(times, now, window_ms):\n    raise NotImplementedError"},"points":150}]$seed$) as seed(collection_slug text,slug text,title text,problem_statement text,difficulty text,topic_tags text[],constraints jsonb,examples jsonb,starter_code_by_language jsonb,points integer);

do $validate_seed$
begin
 if (select count(*) from coding_question_seed)<>20 or (select count(distinct slug) from coding_question_seed)<>20 then raise exception 'Expected exactly 20 distinct questions for backend-api-problem-solving.'; end if;
 if (select count(distinct title) from coding_question_seed)<>20 or (select count(distinct problem_statement) from coding_question_seed)<>20 then raise exception 'Titles and problem statements must be distinct for backend-api-problem-solving.'; end if;
 if exists(select 1 from coding_question_seed where slug=any(array['normalize-page-parameters','unique-request-keys','deduplicate-records','parse-cursor-token','retryable-http-status','exponential-backoff-delays','pagination-window'])) then raise exception 'Seed duplicates a pre-existing backend-api-problem-solving slug.'; end if;
 if exists(select 1 from coding_question_seed s where char_length(btrim(s.title))<10 or char_length(btrim(s.problem_statement))<100 or s.difficulty not in ('Easy','Medium','Hard') or jsonb_typeof(s.constraints)<>'array' or jsonb_array_length(s.constraints)<2 or jsonb_typeof(s.examples)<>'array' or jsonb_array_length(s.examples)<2 or jsonb_typeof(s.starter_code_by_language)<>'object' or not(s.starter_code_by_language ? 'JavaScript') or not(s.starter_code_by_language ? 'Python') or nullif(btrim(s.starter_code_by_language->>'JavaScript'),'') is null or nullif(btrim(s.starter_code_by_language->>'Python'),'') is null or position('Not implemented' in s.starter_code_by_language->>'JavaScript')=0 or position('NotImplementedError' in s.starter_code_by_language->>'Python')=0 or exists(select 1 from jsonb_array_elements(s.examples) e(value) where jsonb_typeof(e.value)<>'object' or e.value->>'input' is null or e.value->>'output' is null or e.value->>'input' in ('[]','[null]','null','') or e.value->>'output' in ('[]','[null]'))) then raise exception 'Question quality validation failed for backend-api-problem-solving.'; end if;
 if (select count(*) from public.coding_test_sets where slug='backend-api-problem-solving' and publication_status='published')<>1 then raise exception 'Expected one published collection: backend-api-problem-solving.'; end if;
 if (select count(*) from public.coding_test_sets where slug='backend-api-problem-solving' and publication_status='published' and jsonb_array_length(supported_languages)=2 and supported_languages @> '["JavaScript","Python"]'::jsonb)<>1 then raise exception 'Expected JavaScript and Python support for backend-api-problem-solving.'; end if;
 if (select count(*) from public.coding_questions q join public.coding_test_sets c on c.id=q.collection_id where c.slug='backend-api-problem-solving')<>7 then raise exception 'Expected exactly 7 existing questions in backend-api-problem-solving.'; end if;
 if (select coalesce(max(q.question_order),0) from public.coding_questions q join public.coding_test_sets c on c.id=q.collection_id where c.slug='backend-api-problem-solving')<>7 then raise exception 'Expected existing backend-api-problem-solving orders to end at 7.'; end if;
end;
$validate_seed$;

with question_rows as (select collection.id collection_id,seed.*,coalesce(existing.max_order,0)+row_number() over(partition by collection.id order by seed.slug)::integer question_order from coding_question_seed seed join public.coding_test_sets collection on collection.slug=seed.collection_slug and collection.publication_status='published' cross join lateral(select max(q.question_order) max_order from public.coding_questions q where q.collection_id=collection.id) existing) insert into public.coding_questions(collection_id,slug,title,problem_statement,difficulty,topic_tags,constraints,examples,starter_code_by_language,points,publication_status,question_order) select collection_id,slug,title,problem_statement,difficulty,topic_tags,constraints,examples,starter_code_by_language,points,'published',question_order from question_rows on conflict(collection_id,slug) do nothing;

insert into public.coding_test_cases(question_id,case_order,test_input,expected_output,visibility) select question.id,example.ordinality::integer,example.value->>'input',example.value->>'output','visible' from coding_question_seed seed join public.coding_test_sets collection on collection.slug=seed.collection_slug join public.coding_questions question on question.collection_id=collection.id and question.slug=seed.slug cross join lateral jsonb_array_elements(seed.examples) with ordinality example(value,ordinality) on conflict(question_id,case_order) do nothing;

commit;
